insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('category-covers', 'category-covers', false, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
create policy "Users read their category covers" on storage.objects for select to authenticated using (bucket_id = 'category-covers' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "Users upload their category covers" on storage.objects for insert to authenticated with check (bucket_id = 'category-covers' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "Users update their category covers" on storage.objects for update to authenticated using (bucket_id = 'category-covers' and (storage.foldername(name))[1] = auth.uid()::text) with check (bucket_id = 'category-covers' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "Users delete their category covers" on storage.objects for delete to authenticated using (bucket_id = 'category-covers' and (storage.foldername(name))[1] = auth.uid()::text);